import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Flows testen","description":"Die Testmöglichkeiten im Flow-Editor und wie Sie Fehler eingrenzen.","frontmatter":{"title":"Flows testen","description":"Die Testmöglichkeiten im Flow-Editor und wie Sie Fehler eingrenzen."},"headers":[],"relativePath":"flows/testen.md","filePath":"flows/testen.md","lastUpdated":1786518403000}'),i={name:"flows/testen.md"};function s(l,e,d,h,o,u){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="flows-testen" tabindex="-1">Flows testen <a class="header-anchor" href="#flows-testen" aria-label="Permalink to &quot;Flows testen&quot;">​</a></h1><p>Ein Flow greift in echte Daten ein und verschickt echte Nachrichten. Testen Sie ihn, bevor er auf produktive Ereignisse reagiert.</p><div class="danger custom-block"><p class="custom-block-title">Ein Testlauf ist kein Trockenlauf</p><p>Ein Test führt den Flow <strong>wirklich</strong> aus: E-Mails gehen raus, Einträge werden angelegt und geändert, fremde Systeme werden aufgerufen.</p><p>Verwenden Sie beim Testen Ihre eigene E-Mail-Adresse und Testdatensätze — keine echten Kundendaten.</p></div><h2 id="die-testarten" tabindex="-1">Die Testarten <a class="header-anchor" href="#die-testarten" aria-label="Permalink to &quot;Die Testarten&quot;">​</a></h2><p>Der Editor bietet mehrere Wege, einen Flow auszuführen:</p><table tabindex="0"><thead><tr><th>Schaltfläche</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Flow ausführen</strong></td><td>Startet den Flow</td></tr><tr><td><strong>Flow testen</strong></td><td><em>Verwendet letzte Zeile des Grids</em></td></tr><tr><td><strong>Erneut starten</strong></td><td><em>Mit Daten aus letzter Ausführung</em></td></tr><tr><td><strong>Mit Test-Daten starten</strong></td><td><em>Gib Beispiel-Daten an</em></td></tr><tr><td><strong>Warten</strong></td><td><em>Warten bis der Flow erneut ausgeführt wird</em></td></tr><tr><td><strong>Mit Daten aus dem Flow Formular</strong></td><td><em>Das Formular öffnen und mit übermittelten Daten testen</em></td></tr></tbody></table><h3 id="flow-testen" tabindex="-1">Flow testen <a class="header-anchor" href="#flow-testen" aria-label="Permalink to &quot;Flow testen&quot;">​</a></h3><p>Der schnellste Weg. Nimmt die letzte Zeile des Grids als Eingabe.</p><div class="tip custom-block"><p class="custom-block-title">Legen Sie sich eine Testzeile an</p><p>Da immer die <em>letzte</em> Zeile verwendet wird, lohnt es sich, ganz unten im Grid einen Testdatensatz zu pflegen — mit Ihrer eigenen E-Mail-Adresse und klar erkennbaren Werten wie <code>TEST Mustermann</code>.</p></div><h3 id="erneut-starten" tabindex="-1">Erneut starten <a class="header-anchor" href="#erneut-starten" aria-label="Permalink to &quot;Erneut starten&quot;">​</a></h3><p>Wiederholt den Flow mit den Daten des letzten Durchlaufs. Ideal beim Beheben eines Fehlers: Sie ändern eine Einstellung und lassen dieselben Eingabedaten erneut durchlaufen.</p><p>Gab es noch keinen Durchlauf, meldet der Editor <em>Es wurde keine vorherige Ausführung gefunden.</em></p><h3 id="mit-test-daten-starten" tabindex="-1">Mit Test-Daten starten <a class="header-anchor" href="#mit-test-daten-starten" aria-label="Permalink to &quot;Mit Test-Daten starten&quot;">​</a></h3><p>Sie geben die Eingabedaten selbst als Beispiel an. Der passende Weg beim Auslöser <strong>Webhook</strong>, wo die Daten sonst von außen kämen.</p><h3 id="warten" tabindex="-1">Warten <a class="header-anchor" href="#warten" aria-label="Permalink to &quot;Warten&quot;">​</a></h3><p>Der Editor wartet auf den nächsten echten Durchlauf und zeigt dessen Daten an. Nützlich, um zu beobachten, was bei einer tatsächlichen Nutzung passiert.</p><h3 id="mit-daten-aus-dem-flow-formular" tabindex="-1">Mit Daten aus dem Flow Formular <a class="header-anchor" href="#mit-daten-aus-dem-flow-formular" aria-label="Permalink to &quot;Mit Daten aus dem Flow Formular&quot;">​</a></h3><p>Öffnet das zugehörige Formular. Was Sie dort absenden, wird zur Testeingabe. Der realistischste Test für formularbasierte Flows.</p><h2 id="ist-der-flow-uberhaupt-testbereit" tabindex="-1">Ist der Flow überhaupt testbereit? <a class="header-anchor" href="#ist-der-flow-uberhaupt-testbereit" aria-label="Permalink to &quot;Ist der Flow überhaupt testbereit?&quot;">​</a></h2><p>Ist alles vollständig konfiguriert, meldet der Editor:</p><blockquote><p><em>Der Flow ist bereit, getestet zu werden</em></p></blockquote><p>Fehlt etwas, erscheint stattdessen:</p><blockquote><p><em>Flow hat noch Fehler</em></p></blockquote><p>Gehen Sie dann die Schritte durch — ein unvollständig konfigurierter Schritt ist im Editor markiert.</p><h2 id="ergebnisse-ansehen" tabindex="-1">Ergebnisse ansehen <a class="header-anchor" href="#ergebnisse-ansehen" aria-label="Permalink to &quot;Ergebnisse ansehen&quot;">​</a></h2><p>Nach einem Durchlauf zeigt der Editor die Daten dieses Laufs an. Der Hinweis lautet <em>Anzeige vorheriger Ausführungen</em> — Sie sehen also nicht den Bauplan, sondern konkrete Werte.</p><p>Angezeigt werden Ausführungszeitpunkt, Status und Anzahl der Schritte. Über <strong>Andere auswählen</strong> springen Sie zu einem anderen Durchlauf, über <strong>Zurücksetzen</strong> verlassen Sie die Ansicht.</p><p>Status eines Durchlaufs:</p><table tabindex="0"><thead><tr><th>Status</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Abgeschlossen</strong> / <em>Fertig</em></td><td>Vollständig durchgelaufen</td></tr><tr><td><strong>Fehlgeschlagen</strong> / <em>Fehler</em></td><td>Abgebrochen</td></tr><tr><td><strong>In Bearbeitung</strong></td><td>Läuft gerade</td></tr><tr><td><strong>Wartet</strong></td><td>Wartet auf ein Ereignis, etwa eine Seiteneingabe</td></tr><tr><td><strong>Testausführung</strong></td><td>Ein Testlauf, kein echter Durchlauf</td></tr></tbody></table><h2 id="fehler-eingrenzen" tabindex="-1">Fehler eingrenzen <a class="header-anchor" href="#fehler-eingrenzen" aria-label="Permalink to &quot;Fehler eingrenzen&quot;">​</a></h2><p>An jedem Schritt führt <strong>Details anzeigen</strong> zu den Ein- und Ausgabedaten, bei Problemen <strong>Fehlerdetails anzeigen</strong> zur Fehlermeldung.</p><p>Ein bewährtes Vorgehen:</p><ol><li><strong>Wo bricht es ab?</strong> Im Verlauf sehen Sie, wie viele Schritte gelaufen sind.</li><li><strong>Was kam an?</strong> Über <em>Details anzeigen</em> am letzten erfolgreichen Schritt prüfen, ob die Ausgabe stimmt.</li><li><strong>Was hat der fehlgeschlagene Schritt erwartet?</strong> Häufig passt ein Feld nicht zum erwarteten Format.</li><li><strong>Ändern und mit „Erneut starten&quot; wiederholen.</strong> Gleiche Eingabe, geänderte Konfiguration.</li></ol><h2 id="haufige-ursachen" tabindex="-1">Häufige Ursachen <a class="header-anchor" href="#haufige-ursachen" aria-label="Permalink to &quot;Häufige Ursachen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Wahrscheinliche Ursache</th></tr></thead><tbody><tr><td>Flow startet gar nicht</td><td>Auslöser zeigt auf ein anderes Grid oder Formular als gedacht</td></tr><tr><td>Flow startet plötzlich nicht mehr</td><td>Der <a href="/flows/was-ist-ein-flow#ein-und-ausschalten">Schalter</a> steht auf <em>aus</em> — womöglich <a href="/flows/durchlaufhistorie#benachrichtigung-bei-fehlern">automatisch nach drei gleichen Fehlern</a></td></tr><tr><td>Flow startet zu oft</td><td><em>Eintrag wurde geändert</em> ohne Feldbedingung</td></tr><tr><td>Flow startet endlos</td><td>Eine Aktion schreibt in dasselbe Grid, das den Flow auslöst</td></tr><tr><td>E-Mail kommt nicht an</td><td>Empfängerfeld leer, weil der Feldwert nicht gesetzt war</td></tr><tr><td>Leere Werte in der Nachricht</td><td>Verweis auf einen Schritt, der noch nichts geliefert hat</td></tr><tr><td>Nur ein Eintrag statt vieler</td><td><em>Alle Einträge laden</em> ohne nachfolgendes <strong>Parallel</strong></td></tr><tr><td><em>Flow hat noch Fehler</em></td><td>Ein Schritt ist unvollständig konfiguriert</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Endlosschleifen unterbrechen</p><p>Löst ein Flow sich selbst aus, entstehen fortlaufend Durchläufe. Schalten Sie ihn zuerst über den <a href="/flows/was-ist-ein-flow#ein-und-ausschalten">Schalter</a> aus — das stoppt sofort, auch die gerade laufenden Ausführungen. Ändern Sie danach in Ruhe den Auslöser oder das Ziel der schreibenden Aktion, schalten Sie wieder ein und prüfen Sie im Verlauf, ob keine neuen Durchläufe mehr entstehen.</p></div><h2 id="vor-dem-produktivbetrieb" tabindex="-1">Vor dem Produktivbetrieb <a class="header-anchor" href="#vor-dem-produktivbetrieb" aria-label="Permalink to &quot;Vor dem Produktivbetrieb&quot;">​</a></h2><p>Eine kurze Prüfliste:</p><ul><li>[ ] Testlauf ohne Fehler durchgelaufen</li><li>[ ] Eine echte Eingabe getestet, nicht nur den Editor-Test</li><li>[ ] Empfängeradressen geprüft — keine Testadressen mehr</li><li>[ ] Bei schreibenden Aktionen: keine Selbstauslösung möglich</li><li>[ ] Bei Webhook-Auslöser: URL nicht öffentlich zugänglich abgelegt</li><li>[ ] Testdatensätze aus dem Grid entfernt</li></ul><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/flows/durchlaufhistorie">Durchlaufhistorie</a></li><li><a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li><li><a href="/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a></li></ul>',41)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
